const BASES={"Alter Reality":"Flashback {1}{U}","Whim of Volrath":"Buyback {2}","Glamerdye":"Retrace","Knight of the Holy Nimbus":"Flanking","Pyretic Hunter":"Menace","Old-Growth Troll":"Trample","Incinerator of the Guilty":"Flying, trample","Timeline Culler":"Haste","Spire Phantasm":"Flying","Memory Vampire":"Flying","Fear of Abduction":"Flying","Chicken Troupe":"Ward {2}","Wall of Shields":"Defender","Windshaper Planetar":"Flash\nFlying","Cultivator Drone":"Devoid","_____ Bird Gets the Worm":"Flying","Bladegraft Aspirant":"Menace","Quick Fixer":"Menace","Angel of Jubilation":"Flying","Legion Angel":"Flying","Strict Proctor":"Flying","Carnival Carnivore":"Deathtouch","Pardic Firecat":"Haste","Glitterflitter":"Flying","Minotaur de Force":"Haste"};
const verifiedSource=Symbol('v88 exact printed source');
export function normalizeCard(card,original){const s=SOURCES[original.name],valid=s&&Object.entries(s).every(([k,v])=>original[k]===v);return {...card,[verifiedSource]:valid?original.name:null};}
export function compileWholeCard(card,h){
 const name=card[verifiedSource];if(!name)return null;
 const base=BASES[name]?h.compileCurrent({...card,oracle_text:BASES[name]}):{implementation:[],implementedKeywords:[],oracleContracts:[]};
 if(BASES[name]&&!base.semanticClass)throw Error('v88 native baseline '+name+': '+base.reason);
 const op={kind:'printed-card-v88',mode:name,contract:'generic-trigger-effect'};
 return {semanticClass:SOURCES[name].type_line.includes('Creature')?'creature-template':'spell-template',implementation:[...base.implementation,op],implementedKeywords:base.implementedKeywords||[],oracleContracts:[...new Set([...(base.oracleContracts||[]),op.contract])],rulesCore:h.stripReminderText(card.oracle_text)};
}
